-- NE-1: Mike Flood (R) vs Chris Backemeyer (D)
UPDATE house_races SET status='General', candidate1_name='Chris Backemeyer', candidate1_party='D', candidate2_name='Mike Flood', candidate2_party='R' WHERE state_code='NE' AND district=1;

-- NE-3: Adrian Smith (R) vs Becky Stille (D)
UPDATE house_races SET status='General', candidate1_name='Becky Stille', candidate1_party='D', candidate2_name='Adrian Smith', candidate2_party='R' WHERE state_code='NE' AND district=3;

-- WV-1: Carol Miller (R) vs Vince George (D)
UPDATE house_races SET status='General', candidate1_name='Vince George', candidate1_party='D', candidate2_name='Carol Miller', candidate2_party='R' WHERE state_code='WV' AND district=1;

-- NE-2 and WV-2 remain Primary (still undecided)
SELECT state_code, district, status, candidate1_name, candidate2_name FROM house_races WHERE state_code IN ('NE','WV') ORDER BY state_code, district;

